from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log


def test_parse_transcript_log_strips_fields_and_skips_blank_lines_and_comments():
    lines = ["", " \t\n", "# comment", " \t# another comment", " a , 1 , 1 ", " b , 2 , 0 ", " c , 3 , "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,not-a-day,0"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["", " # skipped", "valid,1,0", bad_line])


def test_dedupe_keeps_last_record_for_each_id_and_sorts():
    first = {"id": "a", "day": 5, "flagged": True}
    last = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    earlier = {"id": "c", "day": 1, "flagged": None}
    assert dedupe_transcripts([same_day, first, earlier, last]) == [earlier, last, same_day]


def test_daily_flag_counts_fills_gaps_and_ignores_out_of_range_events():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,2,0", "d,2,", "e,4,1", "f,4,1", "g,5,1"])
    assert daily_flag_counts(events, 1, 4) == [1, 0, 0, 2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], 1, 2) == [0, 0]
